/* ================= RENOVO CRETE V15 — PREMIUM GOVERNANCE, KNOWLEDGE & COMMUNITY ================= */
const RC15_VERSION='V15 PREMIUM GOVERNANCE, KNOWLEDGE & COMMUNITY';
const RC15_DOC_TYPES={
 portrait:{label:'Professional / company photo',required:true,accept:'image/*'},
 identity:{label:'Government ID / identity document',required:true,accept:'image/*,.pdf'},
 address:{label:'Proof of address',required:true,accept:'image/*,.pdf'},
 business:{label:'Kbis / business registration / micro-enterprise proof',required:true,accept:'image/*,.pdf'},
 insurance:{label:'Professional / liability insurance',required:false,accept:'image/*,.pdf'},
 nonConviction:{label:'Non-conviction declaration',required:false,accept:'image/*,.pdf,.doc,.docx'},
 nonAffiliation:{label:'Non-affiliation / compliance declaration',required:false,accept:'image/*,.pdf,.doc,.docx'},
 signedContract:{label:'Signed contractor / partner agreement',required:false,accept:'image/*,.pdf'},
 certifications:{label:'Training / certification documents',required:false,accept:'image/*,.pdf'},
 tax:{label:'Tax / VAT supporting document',required:false,accept:'image/*,.pdf'},
 banking:{label:'Bank / payment supporting document',required:false,accept:'image/*,.pdf'},
 other:{label:'Other document',required:false,accept:'image/*,.pdf,.doc,.docx,.xls,.xlsx'}
};
const RC15_ADMIN_DOC_TYPES={portrait:{label:'Administrator photo',required:false,accept:'image/*'},identity:{label:'Government ID',required:true,accept:'image/*,.pdf'},address:{label:'Proof of address',required:true,accept:'image/*,.pdf'},business:{label:'Kbis / business registration (if contractor)',required:false,accept:'image/*,.pdf'},employment:{label:'Employment / appointment document',required:false,accept:'image/*,.pdf,.doc,.docx'},contract:{label:'Signed administration agreement',required:false,accept:'image/*,.pdf'},other:{label:'Other document',required:false,accept:'image/*,.pdf,.doc,.docx,.xls,.xlsx'}};
const RC15_FILE_MAX=50*1024*1024;
function rc15Settings(){
 const s=rc14Settings();
 s.documentationFolders=Array.isArray(s.documentationFolders)?s.documentationFolders:[];
 s.communityThreads=Array.isArray(s.communityThreads)?s.communityThreads:[];
 s.communityMessages=Array.isArray(s.communityMessages)?s.communityMessages:[];
 s.communityArchived=s.communityArchived||{};
 s.communityShowArchives=s.communityShowArchives||{};
 s.communitySelected=s.communitySelected||{};
 s.scopeCostPrices=s.scopeCostPrices||{};
 s.portfolioArchivedIds=Array.isArray(s.portfolioArchivedIds)?s.portfolioArchivedIds:[];
 s.calendarCursor=s.calendarCursor||new Date().toISOString().slice(0,7);
 s.platformAccess=s.platformAccess||{enabled:false,plans:[
  {id:'grid1',name:'ACCESS 01',priceEUR:0,features:['calculator','orders','invoices','documentation','events','community']},
  {id:'grid2',name:'ACCESS 02',priceEUR:0,features:['calculator','orders','invoices','documentation','events','community','visualizer']},
  {id:'grid3',name:'ACCESS 03',priceEUR:0,features:['calculator','orders','invoices','documentation','events','community','visualizer','priority-support']}
 ],assignments:{}};
 s.issuedCredentialHashes=Array.isArray(s.issuedCredentialHashes)?s.issuedCredentialHashes:[];
 if(!s.v15Initialized){
  s.scopeExchangeRates=s.scopeExchangeRates||{};
  if(s.scopeExchangeRates['GLOBAL:ECS']==null)s.scopeExchangeRates['GLOBAL:ECS']=1.20;
  if(s.scopeExchangeRates['REGION:CARIBBEAN']==null)s.scopeExchangeRates['REGION:CARIBBEAN']=1.20;
  s.v15Initialized=true;
 }
 return s;
}
function rc15IsHQ(p=rc11AdminProfile()){return rc12IsWorldHq(p)||rc12IsCaribbeanHq(p)}
function rc15Rate(scope=rc13PricingScope()){const s=rc15Settings();return Math.max(.0001,Number(s.scopeExchangeRates?.[scope]||1.20))}
function rc15CurrencyPair(eurValue,rate=rc15Rate()){const eur=Number(eurValue||0);return{eur,usd:eur*rate}}
function rc15Escape(v){return rc13Safe(v==null?'':v)}
function rc15Initials(name){return String(name||'?').split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'?'}
function rc15CsvDownload(name,rows){const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\n');rc14DownloadText(name,csv,'text/csv')}
function rc15FlagForTerritory(t){if(!t)return'🌐';if(t.regionId==='USA')return'🇺🇸';const n=String(t.name||'').toLowerCase();const map=[['saint-martin','🇫🇷'],['sint maarten','🇸🇽'],['guadeloupe','🇫🇷'],['martinique','🇫🇷'],['saint-barth','🇫🇷'],['st barth','🇫🇷'],['bahamas','🇧🇸'],['barbados','🇧🇧'],['barbade','🇧🇧'],['jamaica','🇯🇲'],['jamaïque','🇯🇲'],['anguilla','🇦🇮'],['antigua','🇦🇬'],['dominica','🇩🇲'],['dominique','🇩🇲'],['germany','🇩🇪'],['allemagne','🇩🇪'],['united kingdom','🇬🇧'],['england','🇬🇧'],['france','🇫🇷'],['spain','🇪🇸'],['italy','🇮🇹'],['netherlands','🇳🇱'],['belgium','🇧🇪'],['switzerland','🇨🇭'],['canada','🇨🇦'],['mexico','🇲🇽'],['brazil','🇧🇷'],['australia','🇦🇺'],['new zealand','🇳🇿'],['japan','🇯🇵'],['singapore','🇸🇬'],['india','🇮🇳'],['south africa','🇿🇦']];for(const[k,f]of map)if(n.includes(k))return f;return'🌐'}

/* 1 — Dashboard KPI cards: every operational KPI is a real navigation target. */
function rc15BindDashboardLinks(){
 const cards=[...document.querySelectorAll('#content .rc-v10-kpi,#content .metric-card,#content .rc11-kpi,#content .card.kpi,#content .rc14-kpi-link')];
 cards.forEach(card=>{const text=card.textContent.toLowerCase();let view='';if(text.includes('revenue')||text.includes('collected'))view='invoices';else if(text.includes('order'))view='global-orders';else if(text.includes('professional')||text.includes('client'))view='clients';else if(text.includes('outstanding')||text.includes('balance')||text.includes('unpaid'))view='receivables';else if(text.includes('message'))view='admin-messages';if(view){card.classList.add('rc15-clickable');card.tabIndex=0;card.setAttribute('role','button');card.onclick=()=>go(view);card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go(view)}}}});
 document.querySelectorAll('#content .rc101-chart,#content .bar-chart').forEach(el=>{el.classList.add('rc15-clickable');el.tabIndex=0;el.onclick=()=>go('global-orders')});
}

/* Professional dashboard: outstanding / overdue always opens the relevant order page. */
const rc15BaseProfessionalDashboard=renderDashboard;
renderDashboard=function(){const html=rc15BaseProfessionalDashboard();return html.replace(/<div class="rc11-kpis">/,`<div class="rc11-kpis rc15-prof-kpis">`)};
function rc15BindProfessionalDashboard(){if(!currentClient()||isAdmin()&&currentView!=='dashboard')return;const cards=[...document.querySelectorAll('#content .rc11-kpi,#content .card.kpi')];cards.forEach(card=>{const t=card.textContent.toLowerCase();let v='';if(t.includes('order'))v='orders';else if(t.includes('outstanding')||t.includes('overdue')||t.includes('instal'))v='orders';else if(t.includes('collected'))v='invoices';else if(t.includes('loyalty'))v='orders';if(v){card.classList.add('rc15-clickable');card.tabIndex=0;card.onclick=()=>go(v)}})}

/* 3 — Remove administrator-only maximum controls from every professional calculator. */
const rc15BaseMultiRenderer=rc101RenderMulti;
rc101RenderMulti=function(){let html=rc15BaseMultiRenderer();if(!isAdmin())html=html.replace(/<label[^>]*>Maximum administrateur[\s\S]*?<\/label>/i,'');return html};

/* 2 — Premium knowledge hub: departments > folders > resources > guided workflow. */
function rc15DocDepartments(){return RC14_DEPARTMENTS}
function rc15DocVisible(d,c){return typeof rc14DocVisibleToClient==='function'?rc14DocVisibleToClient(d,c):true}
function rc15ResourceType(d){if(d.resourceType)return d.resourceType;if(d.url&&/youtu(?:\.be|be\.com)/i.test(d.url))return'YouTube';if(d.url)return'Link';const n=String(d.fileName||'').toLowerCase();if(n.endsWith('.pdf'))return'PDF';if(/\.docx?$/.test(n))return'Word';if(/\.xlsx?$/.test(n))return'Excel';if(/\.(mp4|mov|webm|m4v)$/.test(n))return'Video';if(/\.(jpg|jpeg|png|webp)$/.test(n))return'Image';return d.fileId?'File':'Guide'}
function rc15FolderDocs(dept,folderId,docs){return docs.filter(d=>d.department===dept&&(!folderId||d.folderId===folderId))}
function rc15FolderCards(dept,docs,selected){const folders=rc15Settings().documentationFolders.filter(f=>f.department===dept);return `<div class="rc15-folder-grid"><div class="rc15-folder-card ${selected==='__all'?'active':''}" data-rc15-folder="__all"><b>All resources</b><small>${docs.filter(d=>d.department===dept).length} item(s)</small></div>${folders.map(f=>`<div class="rc15-folder-card ${selected===f.id?'active':''}" data-rc15-folder="${rc15Escape(f.id)}"><b>▰ ${rc15Escape(f.name)}</b><small>${docs.filter(d=>d.folderId===f.id).length} item(s)</small></div>`).join('')}</div>`}
function rc15WorkflowHTML(d,progress){const steps=d.steps||[];if(!steps.length)return'';const done=steps.filter((_,i)=>progress?.[i]).length,pct=Math.round(done/steps.length*100),next=steps.findIndex((_,i)=>!progress?.[i]);return `<div class="rc15-workflow"><div style="display:flex;justify-content:space-between;gap:8px"><b>Guided process</b><small>${done}/${steps.length} completed</small></div><div class="rc15-progress"><span style="width:${pct}%"></span></div>${steps.map((step,i)=>`<label class="rc15-step ${progress?.[i]?'done':''}"><span class="n">${progress?.[i]?'✓':i+1}</span><span><b>${rc15Escape(step)}</b><small>${rc15Escape(d.stepTimes?.[i]||'Complete this step before moving forward.')}</small></span><input type="checkbox" data-rc15-doc-step="${rc15Escape(d.id)}|${i}" ${progress?.[i]?'checked':''}></label>`).join('')}${next>=0?`<div class="rc15-next-step"><b>Next action — Step ${next+1}</b><br>${rc15Escape(steps[next])}${d.reminderText?`<br><small>Reminder: ${rc15Escape(d.reminderText)}</small>`:''}</div>`:'<div class="rc15-next-step"><b>Process completed.</b> All steps are checked.</div>'}</div>`}
function rc15ResourceCard(d,progress,admin=false){const type=rc15ResourceType(d);return `<article class="rc15-resource" data-rc15-resource data-dept="${rc15Escape(d.department)}" data-folder="${rc15Escape(d.folderId||'')}" data-search="${rc15Escape((d.title+' '+(d.description||'')+' '+type).toLowerCase())}"><span class="type">${rc15Escape(type)}</span><h3>${rc15Escape(d.title)}</h3><p>${rc15Escape(d.description||'')}</p><div class="toolbar">${d.url?`<a class="btn primary small" href="${rc15Escape(d.url)}" target="_blank" rel="noopener">${type==='YouTube'?'Watch video':'Open link'}</a>`:''}${d.fileId?`<button class="btn secondary small" data-rc14-open-doc="${rc15Escape(d.fileId)}">Open ${rc15Escape(type)}</button>`:''}${admin?`<button class="btn danger small" data-rc15-delete-resource="${rc15Escape(d.id)}">Delete</button>`:''}</div>${!admin?rc15WorkflowHTML(d,progress):d.steps?.length?`<div class="rc15-next-step"><b>${d.steps.length}-step process</b><br>${rc15Escape(d.steps[0])}</div>`:''}</article>`}
function rc15KnowledgeShell(docs,admin=false){const s=rc15Settings(),state=s.knowledgeState=s.knowledgeState||{},dept=state.department&&rc15DocDepartments().includes(state.department)?state.department:rc15DocDepartments()[0],folder=state.folder||'__all',progress=currentClient()?tenantData().docProgress||{}:{};const filtered=docs.filter(d=>d.department===dept&&(folder==='__all'||d.folderId===folder));return `<div class="rc15-knowledge-shell"><aside class="rc15-knowledge-rail"><h4>Departments</h4><div class="rc15-dept-list">${rc15DocDepartments().map(x=>`<button class="rc15-dept-btn ${x===dept?'active':''}" data-rc15-dept="${rc15Escape(x)}"><span>▦</span>${rc15Escape(x)}<span class="count">${docs.filter(d=>d.department===x).length}</span></button>`).join('')}</div></aside><main class="rc15-library-main"><div class="rc15-library-head"><div><span class="eyebrow">${admin?'KNOWLEDGE GOVERNANCE':'KNOWLEDGE HUB'}</span><h2 style="margin:2px 0">${rc15Escape(dept)}</h2><p style="margin:0;color:#6d8193">Folders, documents, media and guided processes in one controlled workspace.</p></div>${admin?`<div class="toolbar"><button class="btn secondary" id="rc15AddFolder">New folder</button><button class="btn primary" id="rc15AddResource">Add resource / process</button></div>`:''}</div><div class="rc15-library-search"><input id="rc15KnowledgeSearch" placeholder="Search document, topic, process, file type…"><select id="rc15KnowledgeType"><option value="">All formats</option><option>PDF</option><option>Word</option><option>Excel</option><option>Video</option><option>YouTube</option><option>Link</option><option>Image</option></select></div>${rc15FolderCards(dept,docs,folder)}<div class="rc15-resource-grid" id="rc15ResourceGrid">${filtered.map(d=>rc15ResourceCard(d,progress[d.id]||{},admin)).join('')||'<div class="rc12-empty">No resource in this folder yet.</div>'}</div></main></div>`}
renderProfessionalDocumentationV14=function(){const c=currentClient(),docs=rc15Settings().documentationLibrary.filter(d=>rc15DocVisible(d,c));return rc11Hero('Documentation & guided processes','Department-based knowledge, controlled files, training media and step-by-step operating processes.','PROFESSIONAL KNOWLEDGE','',[`${docs.length} resource(s)`])+rc15KnowledgeShell(docs,false)};
renderAdminDocumentationV14=function(){const docs=rc15Settings().documentationLibrary;return rc11Hero('Documentation & process academy','Build a governed knowledge base by department, folder, file format and guided workflow.','PREMIUM KNOWLEDGE GOVERNANCE','',[`${docs.length} resource(s)`])+rc15KnowledgeShell(docs,true)};
function rc15OpenFolderEditor(){const dept=rc15Settings().knowledgeState?.department||RC15_DEPARTMENTS[0];showModal(`<h3>Create folder</h3><div class="field"><label>Department</label><select id="rc15FolderDept">${RC15_DEPARTMENTS.map(x=>`<option ${x===dept?'selected':''}>${rc15Escape(x)}</option>`).join('')}</select></div><div class="field"><label>Folder name</label><input id="rc15FolderName" placeholder="e.g. Sales Process / Proposals / Training"></div><div class="toolbar"><button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn primary" id="rc15FolderSave">Create folder</button></div>`);$('rc15FolderSave').onclick=()=>{const name=$('rc15FolderName').value.trim();if(!name)return toast('Folder name required.');rc15Settings().documentationFolders.push({id:rc11SafeId('folder'),department:$('rc15FolderDept').value,name,createdAt:new Date().toISOString()});saveStore();closeModal();renderShell()}}
function rc15OpenResourceEditor(){const p=rc11AdminProfile(),regions=rc12AllowedRegions(p),clients=rc11VisibleClients(),dept=rc15Settings().knowledgeState?.department||RC15_DEPARTMENTS[0],folders=rc15Settings().documentationFolders.filter(f=>f.department===dept);showModal(`<div class="rc11-modal-wide"><h3>Add premium documentation / process</h3><div class="rc12-modal-grid"><div class="field"><label>Department</label><select id="rc15DocDept">${RC15_DEPARTMENTS.map(x=>`<option ${x===dept?'selected':''}>${rc15Escape(x)}</option>`).join('')}</select></div><div class="field"><label>Folder</label><select id="rc15DocFolder"><option value="">No folder</option>${folders.map(f=>`<option value="${f.id}">${rc15Escape(f.name)}</option>`).join('')}</select></div><div class="field"><label>Priority</label><select id="rc15DocPriority"><option>Normal</option><option>High</option><option>Urgent</option></select></div><div class="field"><label>Resource type</label><select id="rc15DocType"><option>PDF</option><option>Word</option><option>Excel</option><option>Video</option><option>YouTube</option><option>Link</option><option>Image</option><option>Guide</option></select></div><div class="field full"><label>Title</label><input id="rc15DocTitle"></div><div class="field full"><label>Description</label><textarea id="rc15DocDesc" rows="3"></textarea></div><div class="field full"><label>YouTube / web link</label><input id="rc15DocUrl" placeholder="https://..."></div><div class="field full"><label>Upload Word / PDF / Excel / image / video ≤ 50 MB</label><input id="rc15DocFile" type="file" accept=".pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,image/*,video/*"></div><div class="field full"><label>Guided process steps — one per line</label><textarea id="rc15DocSteps" rows="5" placeholder="1. Prepare the client file\n2. Complete the diagnostic\n3. Send the proposal\n4. Follow up"></textarea></div><div class="field full"><label>Timing / instruction for each step — one per line</label><textarea id="rc15StepTimes" rows="4" placeholder="15 min — prepare…\n30 min — complete…"></textarea></div><div class="field full"><label>Reminder / next-action instruction</label><input id="rc15DocReminder" placeholder="Complete within 48 hours before moving to the next stage"></div><div class="field"><label>Audience</label><select id="rc15DocAudience"><option value="region">Region</option><option value="territory">Territory</option><option value="client">Selected professional</option><option value="all">All visible professionals</option></select></div><div class="field"><label>Region</label><select id="rc15DocRegion">${regions.map(r=>`<option value="${r}">${rc15Escape(rc11RegionName(r))}</option>`).join('')}</select></div><div class="field"><label>Territory</label><select id="rc15DocTerritory"></select></div><div class="field"><label>Professional</label><select id="rc15DocClient">${clients.map(c=>`<option value="${c.id}">${rc15Escape(c.company)} — ${rc15Escape(rc11Territory(c.territoryId)?.name||'')}</option>`).join('')}</select></div></div><div class="toolbar"><button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn primary" id="rc15DocSave">Publish</button></div></div>`);const syncFolders=()=>{$('rc15DocFolder').innerHTML='<option value="">No folder</option>'+rc15Settings().documentationFolders.filter(f=>f.department===$('rc15DocDept').value).map(f=>`<option value="${f.id}">${rc15Escape(f.name)}</option>`).join('')};const syncTerr=()=>{$('rc15DocTerritory').innerHTML=rc12AllowedTerritories(p,$('rc15DocRegion').value).map(id=>`<option value="${id}">${rc15Escape(rc11Territory(id)?.name||id)}</option>`).join('')};$('rc15DocDept').onchange=syncFolders;$('rc15DocRegion').onchange=syncTerr;syncFolders();syncTerr();$('rc15DocSave').onclick=async()=>{const title=$('rc15DocTitle').value.trim(),file=$('rc15DocFile').files?.[0];if(!title)return toast('Title required.');if(file&&file.size>RC15_FILE_MAX)return toast('Files over 50 MB must be shared by YouTube / cloud link.');const aud=$('rc15DocAudience').value,d={id:rc11SafeId('doclib'),department:$('rc15DocDept').value,folderId:$('rc15DocFolder').value,priority:$('rc15DocPriority').value,resourceType:$('rc15DocType').value,title,description:$('rc15DocDesc').value.trim(),url:$('rc15DocUrl').value.trim(),steps:$('rc15DocSteps').value.split(/\n+/).map(x=>x.replace(/^\s*\d+[.)-]?\s*/,'').trim()).filter(Boolean),stepTimes:$('rc15StepTimes').value.split(/\n+/).map(x=>x.trim()),reminderText:$('rc15DocReminder').value.trim(),audience:aud,regionIds:aud==='region'?[$('rc15DocRegion').value]:[],territoryIds:aud==='territory'?[$('rc15DocTerritory').value]:[],clientIds:aud==='client'?[$('rc15DocClient').value]:[],createdAt:new Date().toISOString(),createdBy:p?.name||''};if(file){d.fileId=rc11SafeId('knowledge-file');d.fileName=file.name;d.fileSize=file.size;d.fileType=file.type;await rc14SaveBlob(d.fileId,file)}rc15Settings().documentationLibrary.unshift(d);saveStore();closeModal();renderShell();toast('Knowledge resource published.')}}
function rc15BindKnowledge(){const s=rc15Settings();s.knowledgeState=s.knowledgeState||{};document.querySelectorAll('[data-rc15-dept]').forEach(b=>b.onclick=()=>{s.knowledgeState.department=b.dataset.rc15Dept;s.knowledgeState.folder='__all';saveStore();renderShell()});document.querySelectorAll('[data-rc15-folder]').forEach(b=>b.onclick=()=>{s.knowledgeState.folder=b.dataset.rc15Folder;saveStore();renderShell()});const filter=()=>{const q=($('rc15KnowledgeSearch')?.value||'').toLowerCase(),type=$('rc15KnowledgeType')?.value||'';document.querySelectorAll('[data-rc15-resource]').forEach(el=>{const ok=(!q||el.dataset.search.includes(q))&&(!type||el.querySelector('.type')?.textContent.trim()===type);el.style.display=ok?'':'none'})};$('rc15KnowledgeSearch')?.addEventListener('input',filter);$('rc15KnowledgeType')?.addEventListener('change',filter);$('rc15AddFolder')?.addEventListener('click',rc15OpenFolderEditor);$('rc15AddResource')?.addEventListener('click',rc15OpenResourceEditor);document.querySelectorAll('[data-rc15-delete-resource]').forEach(b=>b.onclick=()=>{rc15Settings().documentationLibrary=rc15Settings().documentationLibrary.filter(d=>d.id!==b.dataset.rc15DeleteResource);saveStore();renderShell()});document.querySelectorAll('[data-rc15-doc-step]').forEach(cb=>cb.onchange=()=>{const[id,idx]=cb.dataset.rc15DocStep.split('|'),t=tenantData();t.docProgress=t.docProgress||{};t.docProgress[id]=t.docProgress[id]||{};t.docProgress[id][idx]=cb.checked;saveStore();renderShell()})}

/* 5 — Full month event calendar, click a day or Add Event. */
function rc15MonthKey(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
function rc15CursorDate(){const [y,m]=String(rc15Settings().calendarCursor||'2026-09').split('-').map(Number);return new Date(y||2026,(m||9)-1,1)}
function rc15SetCursor(delta){const d=rc15CursorDate();d.setMonth(d.getMonth()+delta);if(d.getFullYear()<2026)return;rc15Settings().calendarCursor=rc15MonthKey(d);saveStore();renderShell()}
function rc15CalendarEvents(admin){const c=currentClient();return rc15Settings().events.filter(e=>admin?true:rc14EventVisible(e,c))}
function rc15CalendarHTML(admin=false){const cur=rc15CursorDate(),year=cur.getFullYear(),month=cur.getMonth(),firstDay=(new Date(year,month,1).getDay()+6)%7,days=new Date(year,month+1,0).getDate(),prevDays=new Date(year,month,0).getDate(),events=rc15CalendarEvents(admin),names=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'],cells=[];for(let i=0;i<42;i++){let day=i-firstDay+1,cd,muted=false;if(day<1){cd=new Date(year,month-1,prevDays+day);muted=true}else if(day>days){cd=new Date(year,month+1,day-days);muted=true}else cd=new Date(year,month,day);const dateKey=`${cd.getFullYear()}-${String(cd.getMonth()+1).padStart(2,'0')}-${String(cd.getDate()).padStart(2,'0')}`,evs=events.filter(e=>String(e.start||'').slice(0,10)===dateKey);cells.push(`<div class="rc15-day ${muted?'muted':''} ${admin?'admin':''}" ${admin&&!muted?`data-rc15-day="${dateKey}"`:''}><span class="rc15-day-no">${cd.getDate()}</span>${evs.slice(0,4).map(e=>`<button class="rc15-event-pill ${String(e.type||'').toLowerCase()}" data-rc15-event="${rc15Escape(e.id)}" title="${rc15Escape(e.title)}">${rc15Escape(e.title)}</button>`).join('')}${evs.length>4?`<small>+${evs.length-4} more</small>`:''}</div>`)}const label=cur.toLocaleDateString('en-US',{month:'long',year:'numeric'});return `<div class="rc15-calendar-wrap"><div class="rc15-calendar-toolbar"><div><span class="eyebrow">CALENDAR</span><div class="rc15-calendar-title">${rc15Escape(label)}</div></div><div class="toolbar"><button class="btn secondary" id="rc15CalPrev">‹ Previous</button><button class="btn secondary" id="rc15CalToday">Today</button><button class="btn secondary" id="rc15CalNext">Next ›</button>${admin?'<button class="btn primary" id="rc15CalAdd">Add event</button>':''}</div></div><div class="rc15-calendar">${names.map(n=>`<div class="rc15-cal-head">${n}</div>`).join('')}${cells.join('')}</div></div>`}
renderProfessionalEventsV14=function(){const events=rc15CalendarEvents(false);return rc11Hero('Events & training calendar','View your complete month and open the training/event information made available to your account.','EVENTS & TRAINING','',[`${events.length} accessible event(s)`])+rc15CalendarHTML(false)};
renderAdminEventsV14=function(){const events=rc15CalendarEvents(true);return rc11Hero('Events & training calendar','Create events directly from a day cell or the Add Event button. Regional access is applied automatically.','EVENT GOVERNANCE','',[`${events.length} event(s)`])+rc15CalendarHTML(true)};
