/* 6 — Automatic 1.20 EUR→USD pricing conversion + HQ ECS-cost editing. */
const rc15PreviousCatalogPrice=rc11CatalogPrice;
rc11CatalogPrice=function(row,tier='recommended'){
 const base=rc15PreviousCatalogPrice(row,tier),s=rc15Settings(),scope=rc13PricingScope(),rate=rc15Rate(scope),global=s.globalEcsCatalogPrices?.[row.id]?.[tier]||{},localCost=s.scopeCostPrices?.[scope]?.[row.id]?.[tier]||{},localResale=s.scopeResalePrices?.[scope]?.[row.id]?.[tier]||{};
 let costEUR=Number(localCost.costEUR??global.costEUR??base.costEUR??((global.costUSD??base.costUSD??0)/rate));let costUSD=costEUR*rate;
 let resaleEUR=Number(localResale.resaleEUR??base.resaleEUR??base.eur??((localResale.resaleUSD??base.resaleUSD??0)/rate));let resaleUSD=resaleEUR*rate;
 return{...base,costEUR,costUSD,baseUSD:costUSD,resaleEUR,resaleUSD,eur:resaleEUR,exchangeRate:rate};
};
priceOf=function(row,tier){return rc11CatalogPrice(row,tier)};
function rc15CanEditCost(scope,p=rc11AdminProfile()){return rc12IsWorldHq(p)||rc12IsCaribbeanHq(p)&&scope==='REGION:CARIBBEAN'}
function rc15CanSeeCost(p=rc11AdminProfile()){return rc12IsWorldHq(p)||rc12IsCaribbeanHq(p)}
function rc15CatalogSaveRow(btn){const row=btn.closest('tr'),id=btn.dataset.rc15PriceRow,tier=rc11Settings().catalogTier||'recommended',scope=rc13PricingScope(),p=rc11AdminProfile(),s=rc15Settings(),rate=rc15Rate(scope);if(!rc13CanEditScope(scope,p))return toast('No pricing permission.');const costEUR=Number(row.querySelector('[data-rc15-cost-eur]')?.value||0),resaleEUR=Number(row.querySelector('[data-rc15-resale-eur]')?.value||0);if(rc15CanEditCost(scope,p)){if(rc12IsWorldHq(p)){s.globalEcsCatalogPrices[id]=s.globalEcsCatalogPrices[id]||{};s.globalEcsCatalogPrices[id][tier]={costEUR,costUSD:costEUR*rate}}else{s.scopeCostPrices[scope]=s.scopeCostPrices[scope]||{};s.scopeCostPrices[scope][id]=s.scopeCostPrices[scope][id]||{};s.scopeCostPrices[scope][id][tier]={costEUR,costUSD:costEUR*rate}}}if(scope!=='GLOBAL:ECS'){s.scopeResalePrices[scope]=s.scopeResalePrices[scope]||{};s.scopeResalePrices[scope][id]=s.scopeResalePrices[scope][id]||{};s.scopeResalePrices[scope][id][tier]={resaleEUR,resaleUSD:resaleEUR*rate}}saveStore();refreshAllTenantCarts();toast('Pricing updated — calculator synchronized.')}
renderAdminCatalogV11=function(){const p=rc11AdminProfile(),tier=rc11Settings().catalogTier||'recommended',scope=rc13PricingScope(),rate=rc15Rate(scope),rows=allCatalog(),families=[...new Set(rows.map(r=>r.family))].sort(),edit=rc13CanEditScope(scope,p),showCost=rc15CanSeeCost(p),editCost=rc15CanEditCost(scope,p),global=scope==='GLOBAL:ECS',scopes=rc13AdminPricingScopes(p);return rc11Hero('Catalog & pricing governance','EUR is the working reference. The manual EUR→USD rate updates every displayed USD value and synchronizes the simulator. Default: 1 EUR = 1.20 USD.','LIVE PRICING GOVERNANCE','',[`${rows.length} packs`,rc13ScopeLabel(scope)])+`<div class="rc11-catalog-head"><div class="rc11-filters"><div class="field"><label>Pricing scope</label><select id="rc13PricingScope">${scopes.map(x=>`<option value="${rc15Escape(x)}" ${x===scope?'selected':''}>${rc15Escape(rc13ScopeLabel(x))}</option>`).join('')}</select></div><div class="field"><label>Search</label><input id="rc11CatalogSearch" placeholder="Family, product, pack"></div><div class="field"><label>Family</label><select id="rc11CatalogFamily"><option value="">All</option>${families.map(f=>`<option>${rc15Escape(f)}</option>`).join('')}</select></div><div class="field"><label>Price tier</label><select id="rc11CatalogTier"><option value="recommended" ${tier==='recommended'?'selected':''}>Reference</option><option value="large" ${tier==='large'?'selected':''}>Large project</option><option value="premium" ${tier==='premium'?'selected':''}>Premium</option></select></div></div><aside class="rc11-rate-box"><small>Manual EUR → USD rate</small><div class="rc11-rate-value">1 EUR = <span id="rc13RateLabel">${rate.toFixed(4)}</span> USD</div><div class="field"><input id="rc13ManualRate" type="number" min="0.0001" step="0.01" value="${rate}" ${edit?'':'disabled'}></div><div class="rc15-rate-live">LIVE CONVERSION</div><button class="btn primary small" id="rc13SaveRate" ${edit?'':'disabled'}>Apply rate to all USD prices</button></aside></div><section class="rc11-panel" style="margin-top:14px"><div class="table-wrap"><table class="rc11-table"><thead><tr><th>No.</th><th>Family / product</th><th>Pack</th>${showCost?'<th>ECS cost EUR</th><th>ECS cost USD</th>':''}${global?'':'<th>Resale EUR</th><th>Resale USD</th>'}<th>Action</th></tr></thead><tbody>${rows.map((r,i)=>{const pr=rc11CatalogPrice(r,tier);return`<tr data-rc11-catalog-row data-search="${rc15Escape((r.family+' '+r.fullName+' '+r.packLabel).toLowerCase())}" data-family="${rc15Escape(r.family)}"><td>${i+1}</td><td><b>${rc15Escape(r.family)}</b><br><small>${rc15Escape(r.fullName)}</small></td><td>${rc15Escape(r.packLabel)}</td>${showCost?`<td class="rc15-price-cell"><input data-rc15-cost-eur value="${pr.costEUR.toFixed(2)}" ${editCost?'':'disabled'}><small class="rc15-price-hint">Working reference</small></td><td class="rc15-price-cell"><input data-rc15-cost-usd value="${pr.costUSD.toFixed(2)}" ${editCost?'':'disabled'}><small class="rc15-price-hint">Auto from EUR × rate</small></td>`:''}${global?'':`<td class="rc15-price-cell"><input data-rc15-resale-eur value="${pr.resaleEUR.toFixed(2)}" ${edit?'':'disabled'}><small class="rc15-price-hint">Final professional price</small></td><td class="rc15-price-cell"><input data-rc15-resale-usd value="${pr.resaleUSD.toFixed(2)}" ${edit?'':'disabled'}><small class="rc15-price-hint">Auto from EUR × rate</small></td>`}<td>${edit?`<button class="btn primary small" data-rc15-price-row="${rc15Escape(r.id)}">Save</button>`:'<span class="rc11-status">Read only</span>'}</td></tr>`}).join('')}</tbody></table></div></section><div class="hidden" aria-hidden="true"><button id="downloadFullCatalog" type="button"></button><button id="printFullCatalog" type="button"></button><button id="newManualProduct" type="button"></button><select id="adminCatalogTier"><option value="recommended">recommended</option></select></div>`}
function rc15CatalogLiveRate(){const input=$('rc13ManualRate');if(!input)return;const rate=Math.max(.0001,Number(input.value)||1.2);$('rc13RateLabel').textContent=rate.toFixed(4);document.querySelectorAll('#content tbody tr').forEach(row=>{const cE=row.querySelector('[data-rc15-cost-eur]'),cU=row.querySelector('[data-rc15-cost-usd]'),rE=row.querySelector('[data-rc15-resale-eur]'),rU=row.querySelector('[data-rc15-resale-usd]');if(cE&&cU)cU.value=(Number(cE.value||0)*rate).toFixed(2);if(rE&&rU)rU.value=(Number(rE.value||0)*rate).toFixed(2)})}
function rc15BindCatalog(){const scope=rc13PricingScope();$('rc13PricingScope')?.addEventListener('change',e=>{rc13Settings().pricingTarget=e.target.value;saveStore();renderShell()});$('rc11CatalogSearch')?.addEventListener('input',()=>{const q=$('rc11CatalogSearch').value.toLowerCase(),f=$('rc11CatalogFamily')?.value||'';document.querySelectorAll('[data-rc11-catalog-row]').forEach(r=>r.style.display=(!q||r.dataset.search.includes(q))&&(!f||r.dataset.family===f)?'':'none')});$('rc11CatalogFamily')?.addEventListener('change',()=>$('rc11CatalogSearch')?.dispatchEvent(new Event('input')));$('rc11CatalogTier')?.addEventListener('change',e=>{rc11Settings().catalogTier=e.target.value;saveStore();renderShell()});$('rc13ManualRate')?.addEventListener('input',rc15CatalogLiveRate);$('rc13ManualRate')?.addEventListener('change',rc15CatalogLiveRate);$('rc13SaveRate')?.addEventListener('click',()=>{const v=Math.max(.0001,Number($('rc13ManualRate').value)||1.2);if(!rc13CanEditScope(scope))return toast('No permission.');rc15Settings().scopeExchangeRates[scope]=v;const tier=rc11Settings().catalogTier||'recommended';document.querySelectorAll('[data-rc15-price-row]').forEach(b=>rc15CatalogSaveRow(b));saveStore();refreshAllTenantCarts();renderShell();toast('Rate applied to all prices and simulator.')});document.querySelectorAll('[data-rc15-price-row]').forEach(b=>b.onclick=()=>rc15CatalogSaveRow(b));document.querySelectorAll('[data-rc15-cost-usd]').forEach(inp=>inp.addEventListener('change',()=>{const rate=Number($('rc13ManualRate')?.value||1.2),eur=inp.closest('tr').querySelector('[data-rc15-cost-eur]');if(eur)eur.value=(Number(inp.value||0)/rate).toFixed(2)}));document.querySelectorAll('[data-rc15-resale-usd]').forEach(inp=>inp.addEventListener('change',()=>{const rate=Number($('rc13ManualRate')?.value||1.2),eur=inp.closest('tr').querySelector('[data-rc15-resale-eur]');if(eur)eur.value=(Number(inp.value||0)/rate).toFixed(2)}))}

