renderPortfolioV11=function(){const archived=new Set(rc15Settings().portfolioArchivedIds),clients=rc11VisibleClients().map(c=>({c,s:rcClientStats(c)})).sort((a,b)=>b.s.net-a.s.net);return rc11Hero('Client portfolio','Select, filter, archive, restore or export professional records. Permanent deletion is blocked when order history exists.','CLIENT VALUE & GOVERNANCE','',[`${clients.length} client(s)`])+`<div class="rc15-bulkbar"><button class="btn secondary small" id="rc15PortSelectVisible">Select visible</button><button class="btn secondary small" id="rc15PortClear">Clear</button><button class="btn secondary small" id="rc15PortArchive">Archive selected</button><button class="btn secondary small" id="rc15PortRestore">Restore selected</button><button class="btn danger small" id="rc15PortDelete">Delete selected</button><button class="btn primary small" id="rc15PortExport">Export selected CSV</button><span class="spacer"></span><select id="rc15PortStatus"><option value="">All records</option><option value="active">Active only</option><option value="archived">Archived only</option></select></div>${rc12DataFilter('rc12Port',clients.map(x=>x.c))}<section class="rc11-panel"><div class="table-wrap"><table class="rc11-table"><thead><tr><th>Select</th><th>No.</th><th>Client</th><th>Region</th><th>Territory</th><th>Type</th><th>Orders</th><th>Purchases</th><th>Collected</th><th>Balance</th><th>Status</th></tr></thead><tbody id="rc12PortBody">${clients.map((x,i)=>{const a=archived.has(x.c.id);return`<tr data-rc15-port-row data-id="${x.c.id}" data-search="${rc15Escape(`${x.c.company} ${rcClientName(x.c)} ${(x.c.clientType||'')}`.toLowerCase())}" data-region="${x.c.regionId}" data-territory="${x.c.territoryId}" data-archived="${a?'yes':'no'}" class="${a?'rc15-archived':''}"><td><input type="checkbox" data-rc15-port-select="${x.c.id}"></td><td>${i+1}</td><td><button class="btn secondary small" data-rc13-client-sheet="${x.c.id}">${rc15Escape(x.c.company)}</button><br><small>${rc15Escape(rcClientName(x.c))}</small></td><td>${rc15Escape(rc11RegionName(x.c.regionId))}</td><td>${rc15Escape(rc11Territory(x.c.territoryId)?.name||'')}</td><td>${rc15Escape(x.c.clientType||x.c.category||'Professional')}</td><td>${x.s.orders.length}</td><td>${rc11Money(x.s.net)}</td><td>${rc11Money(x.s.paid)}</td><td>${rc11Money(x.s.balance)}</td><td>${a?'<span class="rc15-badge-archived">ARCHIVED</span>':'<span class="rc11-status ok">ACTIVE</span>'}</td></tr>`}).join('')}</tbody></table></div></section><div id="rc101PortfolioResults" class="hidden"></div>`}
function rc15PortfolioSelected(){return [...document.querySelectorAll('[data-rc15-port-select]:checked')].map(x=>x.dataset.rc15PortSelect)}
function rc15ApplyPortfolioFilters(){const q=($('rc12PortSearch')?.value||'').toLowerCase(),r=$('rc12PortRegion')?.value||'',t=$('rc12PortTerritory')?.value||'',status=$('rc15PortStatus')?.value||'';document.querySelectorAll('[data-rc15-port-row]').forEach(el=>{const ok=(!q||el.dataset.search.includes(q))&&(!r||el.dataset.region===r)&&(!t||el.dataset.territory===t)&&(!status||(status==='archived')===(el.dataset.archived==='yes'));el.style.display=ok?'':'none'})}
function rc15BindPortfolio(){['rc12PortSearch','rc12PortRegion','rc12PortTerritory','rc15PortStatus'].forEach(id=>$(id)?.addEventListener(id.includes('Search')?'input':'change',rc15ApplyPortfolioFilters));$('rc15PortSelectVisible')?.addEventListener('click',()=>document.querySelectorAll('[data-rc15-port-row]').forEach(r=>{if(r.style.display!=='none')r.querySelector('[data-rc15-port-select]').checked=true}));$('rc15PortClear')?.addEventListener('click',()=>document.querySelectorAll('[data-rc15-port-select]').forEach(x=>x.checked=false));$('rc15PortArchive')?.addEventListener('click',()=>{const s=rc15Settings(),set=new Set(s.portfolioArchivedIds);rc15PortfolioSelected().forEach(id=>set.add(id));s.portfolioArchivedIds=[...set];saveStore();renderShell()});$('rc15PortRestore')?.addEventListener('click',()=>{const ids=new Set(rc15PortfolioSelected());rc15Settings().portfolioArchivedIds=rc15Settings().portfolioArchivedIds.filter(id=>!ids.has(id));saveStore();renderShell()});$('rc15PortDelete')?.addEventListener('click',()=>{const ids=rc15PortfolioSelected();if(!ids.length)return toast('Select at least one record.');const blocked=ids.filter(id=>(store.tenants[id]?.orders||[]).length);if(blocked.length)return toast(`${blocked.length} selected profile(s) have orders and cannot be permanently deleted. Archive them instead.`);store.accounts=store.accounts.filter(a=>!ids.includes(a.id));ids.forEach(id=>delete store.tenants[id]);saveStore();renderShell()});$('rc15PortExport')?.addEventListener('click',()=>{const ids=rc15PortfolioSelected(),rows=[['No.','Company','Contact','Email','Phone','Type','Region','Territory','Orders','Purchases EUR','Collected EUR','Outstanding EUR']];ids.forEach((id,i)=>{const c=store.accounts.find(x=>x.id===id),s=c?rcClientStats(c):null;if(c&&s)rows.push([i+1,c.company,rcClientName(c),c.email,c.phone,c.clientType||c.category,rc11RegionName(c.regionId),rc11Territory(c.territoryId)?.name||'',s.orders.length,s.net,s.paid,s.balance])});rc15CsvDownload(`RENOVO_CRETE_Portfolio_${new Date().toISOString().slice(0,10)}.csv`,rows)})}

/* 7 — Premium Community: WhatsApp-like threaded messaging for MD/admins and professionals. */
function rc15CommunityRole(){return isAdmin()&&!currentClient()?'admin':'professional'}
function rc15CommunityIdentity(){if(rc15CommunityRole()==='admin'){const p=rc11AdminProfile();return{id:'admin:'+p?.id,name:p?.name||currentAccount()?.contact||'Administrator',regionId:p?.regionId,territoryId:p?.territoryId}}const c=currentClient();return{id:'pro:'+c?.id,name:rcClientName(c)||c?.company||'Professional',regionId:c?.regionId,territoryId:c?.territoryId}}
function rc15CommunityDirectory(){if(rc15CommunityRole()==='admin')return (store.adminProfiles||[]).filter(a=>a.active!==false).map(a=>({id:'admin:'+a.id,name:a.name,subtitle:`${rc11RegionName(a.regionId)} · ${rc11Territory(a.territoryId)?.name||''}`,regionId:a.regionId,territoryId:a.territoryId}));return (store.accounts||[]).filter(a=>a.role==='client'&&a.active).map(c=>({id:'pro:'+c.id,name:rcClientName(c)||c.company,subtitle:`${c.company} · ${rc11RegionName(c.regionId)} · ${rc11Territory(c.territoryId)?.name||''}`,regionId:c.regionId,territoryId:c.territoryId}))}
function rc15DefaultThreads(){const me=rc15CommunityIdentity(),role=rc15CommunityRole(),regionName=rc11RegionName(me.regionId);return role==='admin'?[{id:'admin:global',name:'MD Global Community',kind:'group',subtitle:'All authorized administrators worldwide'},{id:`admin:region:${me.regionId}`,name:`${regionName} MD Group`,kind:'group',subtitle:'Regional administration channel'}]:[{id:'pro:global',name:'Global Professional Community',kind:'group',subtitle:'Professionals across all operating regions'},{id:`pro:region:${me.regionId}`,name:`${regionName} Professionals`,kind:'group',subtitle:'Regional professional channel'}]}
function rc15Threads(){const role=rc15CommunityRole(),me=rc15CommunityIdentity(),s=rc15Settings(),custom=s.communityThreads.filter(t=>t.role===role&&(t.participants||[]).includes(me.id)),all=[...rc15DefaultThreads(),...custom],show=!!s.communityShowArchives[role];return all.filter(t=>show?!!s.communityArchived[t.id]:!s.communityArchived[t.id])}
function rc15SelectedThread(){const role=rc15CommunityRole(),s=rc15Settings(),threads=rc15Threads(),id=s.communitySelected[role];return threads.find(t=>t.id===id)||threads[0]}
function rc15ThreadMessages(id){return rc15Settings().communityMessages.filter(m=>m.threadId===id).sort((a,b)=>new Date(a.createdAt)-new Date(b.createdAt))}
function rc15CommunityHTML(){const role=rc15CommunityRole(),me=rc15CommunityIdentity(),threads=rc15Threads(),selected=rc15SelectedThread(),messages=selected?rc15ThreadMessages(selected.id):[];return rc11Hero(role==='admin'?'MD Community':'Professional Community',role==='admin'?'Private administration communication: global groups, regional groups, direct messages, files and searchable archives.':'Connect with professionals by region or worldwide. Exchange messages, documents, images and lightweight media.','COMMUNITY & COLLABORATION',`<button class="btn primary" id="rc15NewConversation">New conversation / group</button>`,[`${threads.length} thread(s)`])+`<div class="rc15-community-shell"><aside class="rc15-community-sidebar"><div class="rc15-community-sidehead"><input id="rc15CommunitySearch" placeholder="Search name, group, subject…"><div class="rc15-compose-tools"><select id="rc15CommunityFilter"><option value="">All conversations</option><option value="group">Groups</option><option value="direct">Direct</option></select><select id="rc15CommunityDate"><option value="">All dates</option><option value="7">7 days</option><option value="30">30 days</option><option value="365">1 year</option></select><button class="btn secondary small" id="rc15CommunityArchiveToggle">${rc15Settings().communityShowArchives[role]?'Active':'Archives'}</button></div></div><div class="rc15-thread-list">${threads.map(t=>{const last=rc15ThreadMessages(t.id).slice(-1)[0];return`<button class="rc15-thread ${selected?.id===t.id?'active':''}" data-rc15-thread="${rc15Escape(t.id)}" data-kind="${rc15Escape(t.kind||'group')}" data-search="${rc15Escape((t.name+' '+(t.subtitle||'')+' '+(last?.text||'')).toLowerCase())}" data-time="${last?new Date(last.createdAt).getTime():0}"><span class="rc15-avatar">${rc15Escape(rc15Initials(t.name))}</span><span><b>${rc15Escape(t.name)}</b><small>${rc15Escape(last?.text||t.subtitle||'No message yet')}</small></span><small>${last?new Date(last.createdAt).toLocaleDateString() : ''}</small></button>`}).join('')}</div></aside><main class="rc15-community-main">${selected?`<header class="rc15-chat-head"><div><b>${rc15Escape(selected.name)}</b><br><small>${rc15Escape(selected.subtitle||'Secure community thread')}</small></div><button class="btn secondary small" id="rc15ArchiveThread">Archive</button></header><section class="rc15-chat-messages" id="rc15ChatMessages">${messages.map(m=>`<article class="rc15-msg ${m.senderId===me.id?'mine':''}"><div class="meta">${rc15Escape(m.senderName)} · ${rc15Escape(m.regionLabel||'')} · ${new Date(m.createdAt).toLocaleString()}</div><p>${rc15Escape(m.text||'')}</p>${m.link?`<div class="rc15-attachment"><span>🔗 ${rc15Escape(m.link)}</span><a href="${rc15Escape(m.link)}" target="_blank" rel="noopener">Open</a></div>`:''}${m.fileId?`<div class="rc15-attachment"><span>▧ ${rc15Escape(m.fileName)} · ${Math.round((m.fileSize||0)/1024/1024*10)/10} MB</span><button class="btn secondary small" data-rc15-open-community-file="${rc15Escape(m.fileId)}">Open</button></div>`:''}</article>`).join('')||'<div class="rc12-empty">Start the conversation.</div>'}</section><footer class="rc15-compose"><div class="rc15-compose-row"><textarea id="rc15MessageText" placeholder="Write a message…"></textarea><button class="btn primary" id="rc15SendMessage">Send</button></div><div class="rc15-compose-tools"><input id="rc15MessageFile" type="file" accept=".pdf,.doc,.docx,.xls,.xlsx,image/*,video/*"><input id="rc15MessageLink" placeholder="Optional YouTube / cloud link" style="min-width:220px;flex:1"><span class="rc15-file-limit">Files ≤ 50 MB. Larger video: share a link.</span></div></footer>`:'<div class="rc12-empty">No conversation selected.</div>'}</main></div>`}
function renderCommunityV15(){return rc15CommunityHTML()}
function rc15OpenNewConversation(){const role=rc15CommunityRole(),dir=rc15CommunityDirectory(),me=rc15CommunityIdentity();showModal(`<div class="rc11-modal-wide"><h3>New ${role==='admin'?'MD':'professional'} conversation</h3><div class="field"><label>Conversation type</label><select id="rc15ConvType"><option value="direct">Direct message</option><option value="group">Group</option></select></div><div class="field"><label>Group / subject name</label><input id="rc15ConvName" placeholder="Project, training cohort, region, subject…"></div><div class="rc15-folder-grid">${dir.filter(x=>x.id!==me.id).map(x=>`<label class="rc15-folder-card"><input type="checkbox" data-rc15-conv-person="${rc15Escape(x.id)}"> <b>${rc15Escape(x.name)}</b><small>${rc15Escape(x.subtitle)}</small></label>`).join('')}</div><div class="toolbar"><button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn primary" id="rc15ConvCreate">Create conversation</button></div></div>`);$('rc15ConvCreate').onclick=()=>{const ids=[...document.querySelectorAll('[data-rc15-conv-person]:checked')].map(x=>x.dataset.rc15ConvPerson),kind=$('rc15ConvType').value;if(!ids.length)return toast('Select at least one participant.');if(kind==='direct'&&ids.length>1)return toast('Direct message: select one person only.');const other=dir.find(x=>x.id===ids[0]),name=kind==='direct'?(other?.name||'Direct message'):($('rc15ConvName').value.trim()||'New group'),t={id:rc11SafeId('thread'),role,kind,name,subtitle:kind==='direct'?'Direct conversation':`${ids.length+1} members`,participants:[me.id,...ids],createdAt:new Date().toISOString()};rc15Settings().communityThreads.unshift(t);rc15Settings().communitySelected[role]=t.id;saveStore();closeModal();renderShell()}}
async function rc15SendCommunityMessage(){const selected=rc15SelectedThread(),me=rc15CommunityIdentity(),text=$('rc15MessageText')?.value.trim()||'',link=$('rc15MessageLink')?.value.trim()||'',file=$('rc15MessageFile')?.files?.[0];if(!selected)return;if(!text&&!link&&!file)return toast('Write a message or attach a file/link.');if(file&&file.size>RC15_FILE_MAX)return toast('File exceeds 50 MB. Upload the video to YouTube/cloud and share the link.');const m={id:rc11SafeId('msg'),threadId:selected.id,senderId:me.id,senderName:me.name,regionLabel:`${rc11RegionName(me.regionId)} · ${rc11Territory(me.territoryId)?.name||''}`,text,link,createdAt:new Date().toISOString()};if(file){m.fileId=rc11SafeId('community-file');m.fileName=file.name;m.fileType=file.type;m.fileSize=file.size;await rc14SaveBlob(m.fileId,file)}rc15Settings().communityMessages.push(m);saveStore();renderShell()}
function rc15BindCommunity(){document.querySelectorAll('[data-rc15-thread]').forEach(b=>b.onclick=()=>{rc15Settings().communitySelected[rc15CommunityRole()]=b.dataset.rc15Thread;saveStore();renderShell()});$('rc15NewConversation')?.addEventListener('click',rc15OpenNewConversation);$('rc15SendMessage')?.addEventListener('click',rc15SendCommunityMessage);$('rc15MessageText')?.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();rc15SendCommunityMessage()}});document.querySelectorAll('[data-rc15-open-community-file]').forEach(b=>b.onclick=()=>rc14OpenProfileDocument(b.dataset.rc15OpenCommunityFile));const filter=()=>{const q=($('rc15CommunitySearch')?.value||'').toLowerCase(),kind=$('rc15CommunityFilter')?.value||'',days=Number($('rc15CommunityDate')?.value||0),cut=days?Date.now()-days*86400000:0;document.querySelectorAll('[data-rc15-thread]').forEach(b=>b.style.display=(!q||b.dataset.search.includes(q))&&(!kind||b.dataset.kind===kind)&&(!cut||Number(b.dataset.time||0)>=cut)?'':'none')};$('rc15CommunitySearch')?.addEventListener('input',filter);$('rc15CommunityFilter')?.addEventListener('change',filter);$('rc15CommunityDate')?.addEventListener('change',filter);$('rc15CommunityArchiveToggle')?.addEventListener('click',()=>{const role=rc15CommunityRole();rc15Settings().communityShowArchives[role]=!rc15Settings().communityShowArchives[role];saveStore();renderShell()});$('rc15ArchiveThread')?.addEventListener('click',()=>{const t=rc15SelectedThread();if(t){rc15Settings().communityArchived[t.id]=true;saveStore();toast('Conversation archived.');renderShell()}});setTimeout(()=>{const box=$('rc15ChatMessages');if(box)box.scrollTop=box.scrollHeight},0)}

/* 8 & 9 — Expanded professional dossier: photo, document tabs, sortable recent orders. */
function rc15DocMeta(accountId,type){return rc14ProfileDocs(accountId).filter(d=>d.docType===type).slice().sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt))[0]}
function rc15DocTabs(accountId,types){return `<div class="rc15-doc-tabs">${Object.entries(types).map(([k,v])=>{const d=rc15DocMeta(accountId,k);return`<button class="rc15-doc-tab ${d?'ok':'missing'}" ${d?`data-rc14-open-doc="${d.id}"`:''}>${d?'✓':'○'} ${rc15Escape(v.label)}${v.required?' *':''}</button>`}).join('')}</div>`}
function rc15ProfilePhotoDoc(accountId){return rc15DocMeta(accountId,'portrait')}
async function rc15HydrateProfileImages(){for(const img of document.querySelectorAll('[data-rc15-photo-doc]')){try{const b=await rc14LoadBlob(img.dataset.rc15PhotoDoc);if(b){const u=URL.createObjectURL(b);img.src=u;img.onload=()=>setTimeout(()=>URL.revokeObjectURL(u),60000)}}catch(e){}}}
function rc15RecentOrdersHTML(c){const orders=(store.tenants[c.id]?.orders||[]).slice().sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)),systems=[...new Set(orders.map(o=>o.systemName||rcSystemKey(o)))].sort();return `<section class="rc13-notes"><div class="rc11-section-head"><div><span class="eyebrow">RECENT ORDERS</span><h3>Numbered order history</h3></div></div><div class="rc12-filters"><div class="field"><label>Search</label><input id="rc15ProOrderSearch" placeholder="Order, project, system"></div><div class="field"><label>System</label><select id="rc15ProOrderSystem"><option value="">All</option>${systems.map(s=>`<option>${rc15Escape(s)}</option>`).join('')}</select></div><div class="field"><label>Sort</label><select id="rc15ProOrderSort"><option value="date-desc">Newest → oldest</option><option value="date-asc">Oldest → newest</option><option value="amount-desc">Amount high → low</option><option value="amount-asc">Amount low → high</option><option value="system">System A → Z</option></select></div></div><div class="table-wrap"><table class="rc11-table"><thead><tr><th>No.</th><th>Order</th><th>Date</th><th>System</th><th>Total</th><th>Payment</th></tr></thead><tbody id="rc15ProOrderBody">${orders.map((o,i)=>`<tr data-rc15-pro-order data-search="${rc15Escape((rc11OrderDisplay(o)+' '+(o.project||'')+' '+(o.systemName||rcSystemKey(o))).toLowerCase())}" data-system="${rc15Escape(o.systemName||rcSystemKey(o))}" data-date="${new Date(o.createdAt).getTime()}" data-amount="${Number(o.totalEUR||0)}"><td>${String(i+1).padStart(3,'0')}</td><td>${rc15Escape(rc11OrderDisplay(o))}</td><td>${rc15Escape(rc11Date(o.createdAt))}</td><td>${rc15Escape(o.systemName||rcSystemKey(o))}</td><td>${rc11Money(o.totalEUR)}</td><td>${rc15Escape(o.paymentStatus||'')}</td></tr>`).join('')||'<tr><td colspan="6">No order.</td></tr>'}</tbody></table></div></section>`}
function rc15ProfessionalSheet(id){const c=(store.accounts||[]).find(x=>x.id===id&&x.role==='client');if(!c||!rc11CanSeeClient(c))return toast('No permission.');const s=rcClientStats(c),can=rc11CanManageClient(c),photo=rc15ProfilePhotoDoc(c.id),assign=[c.territoryId,...(c.additionalTerritoryIds||[])].filter(Boolean);showModal(`<div class="rc11-modal-wide rc13-profile-sheet"><div class="rc15-profile-hero"><img class="rc15-profile-avatar" ${photo?`data-rc15-photo-doc="${photo.id}"`:''} alt="Profile photo"><div><span class="eyebrow">PROFESSIONAL MASTER FILE</span><h2 style="margin:2px 0">${rc15Escape(c.company)}</h2><p style="margin:0">${rc15Escape(rcClientName(c))} · ${rc15Escape(c.clientType||c.category||'Professional')}</p></div><span class="rc11-status ${c.active?'ok':'danger'}">${c.active?'Active':'Inactive'}</span></div><div class="rc13-profile-grid" style="margin-top:14px"><section><h4>Identity & company</h4><p><b>Legal name:</b> ${rc15Escape(c.legalName||c.company||'—')}<br><b>Registration / SIRET / SIREN:</b> ${rc15Escape(c.registrationNumber||c.siret||'—')}<br><b>VAT / Tax ID:</b> ${rc15Escape(c.vatNumber||'—')}<br><b>Exact type:</b> ${rc15Escape(c.clientType||'—')}<br><b>Business activity:</b> ${rc15Escape(c.businessActivity||'—')}</p></section><section><h4>Contact & login</h4><p><b>Email / login:</b> ${rc15Escape(c.email||'—')}<br><b>Phone:</b> ${rc15Escape(c.phone||'—')}<br><b>Secondary phone:</b> ${rc15Escape(c.secondaryPhone||'—')}<br><b>WhatsApp:</b> ${rc15Escape(c.whatsapp||c.phone||'—')}<br><b>Website:</b> ${rc15Escape(c.website||'—')}</p></section><section><h4>Address</h4><p>${rc15Escape(c.address1||'—')}<br>${rc15Escape(c.address2||'')}<br>${rc15Escape([c.postalCode,c.city,c.country].filter(Boolean).join(' · '))}</p></section><section><h4>Operating assignments</h4><div class="rc15-assignment-chips">${assign.map(tid=>`<span class="rc15-assignment">${rc15FlagForTerritory(rc11Territory(tid))} ${rc15Escape(rc11Territory(tid)?.name||tid)}</span>`).join('')}</div></section></div><div class="rc11-kpis">${rc11Kpi('Orders',s.orders.length,'')}${rc11Kpi('Purchased',rc11Money(s.net),'')}${rc11Kpi('Collected',rc11Money(s.paid),'','success')}${rc11Kpi('Outstanding',rc11Money(s.balance),'','danger')}</div><section class="rc13-notes"><h3>Identity, company & compliance documents</h3>${rc15DocTabs(c.id,RC15_DOC_TYPES)}<p><small>* Required for standard professional onboarding. Optional categories can be added as business rules evolve.</small></p></section>${rc15RecentOrdersHTML(c)}<div class="toolbar">${can?`<button class="btn primary" data-rc13-edit-client-modal="${c.id}">Edit profile</button><button class="btn dark" data-rc13-open-client="${c.id}">Open professional portal</button><button class="btn secondary" data-rc14-credential="${c.id}">Generate & send 24h login</button><button class="btn secondary" data-rc15-assign-pro="${c.id}">Assign additional territory</button>`:''}<a class="btn secondary" href="mailto:${encodeURIComponent(c.email||'')}">Email</a><button class="btn secondary" onclick="closeModal()">Close</button></div></div>`);setTimeout(rc15HydrateProfileImages,0);setTimeout(rc15BindProfessionalOrderFilters,0)}
rc13OpenProfessionalSheet=rc15ProfessionalSheet;
function rc15BindProfessionalOrderFilters(){const filter=()=>{const q=($('rc15ProOrderSearch')?.value||'').toLowerCase(),sys=$('rc15ProOrderSystem')?.value||'';document.querySelectorAll('[data-rc15-pro-order]').forEach(r=>r.style.display=(!q||r.dataset.search.includes(q))&&(!sys||r.dataset.system===sys)?'':'none')};$('rc15ProOrderSearch')?.addEventListener('input',filter);$('rc15ProOrderSystem')?.addEventListener('change',filter);$('rc15ProOrderSort')?.addEventListener('change',e=>{const body=$('rc15ProOrderBody'),rows=[...body.querySelectorAll('[data-rc15-pro-order]')],v=e.target.value;rows.sort((a,b)=>v==='date-asc'?a.dataset.date-b.dataset.date:v==='date-desc'?b.dataset.date-a.dataset.date:v==='amount-asc'?a.dataset.amount-b.dataset.amount:v==='amount-desc'?b.dataset.amount-a.dataset.amount:a.dataset.system.localeCompare(b.dataset.system));rows.forEach(r=>body.appendChild(r))})}
function rc15AssignProfessionalTerritory(id){const c=store.accounts.find(x=>x.id===id),p=rc11AdminProfile();if(!c||!rc11CanManageClient(c))return;const allowed=rc11Territories().filter(t=>rc12CanSeeTerritory(t.id,p)&&t.id!==c.territoryId&&!(c.additionalTerritoryIds||[]).includes(t.id));showModal(`<h3>Assign professional to another territory</h3><p>Primary territory remains ${rc15Escape(rc11Territory(c.territoryId)?.name||'')}. Add an exceptional secondary operating territory.</p><div class="field"><label>Additional territory</label><select id="rc15ProAssignTerr">${allowed.map(t=>`<option value="${t.id}">${rc15FlagForTerritory(t)} ${rc15Escape(rc11RegionName(t.regionId))} · ${rc15Escape(t.name)}</option>`).join('')}</select></div><div class="toolbar"><button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn primary" id="rc15ProAssignSave">Assign</button></div>`);$('rc15ProAssignSave').onclick=()=>{const tid=$('rc15ProAssignTerr').value;c.additionalTerritoryIds=[...new Set([...(c.additionalTerritoryIds||[]),tid])];saveStore();closeModal();rc15ProfessionalSheet(id)}}

/* Self professional profile: same extended document taxonomy. */
renderProfessionalProfileV14=function(){const c=currentClient();if(!c)return'';const photo=rc15ProfilePhotoDoc(c.id);return rc11Hero('My professional profile','Maintain your company, contact and compliance information. Your login email remains protected.','MY PROFESSIONAL FILE','',[`${rc15Escape(rc11RegionName(c.regionId))} · ${rc15Escape(rc11Territory(c.territoryId)?.name||'')}`])+`<div class="rc15-profile-hero"><img class="rc15-profile-avatar" ${photo?`data-rc15-photo-doc="${photo.id}"`:''} alt="Professional photo"><div><h2>${rc15Escape(c.company)}</h2><p>${rc15Escape(rcClientName(c))} · ${rc15Escape(c.clientType||'Professional')}</p></div><span class="rc14-identity-badge">Login: ${rc15Escape(c.email)}</span></div><section class="rc11-panel" style="margin-top:14px"><div class="rc12-modal-grid"><div class="field"><label>Company / trading name</label><input id="rc14PFCompany" value="${rc15Escape(c.company||'')}"></div><div class="field"><label>Legal name</label><input id="rc14PFLegal" value="${rc15Escape(c.legalName||'')}"></div><div class="field"><label>First name</label><input id="rc14PFFirst" value="${rc15Escape(c.firstName||'')}"></div><div class="field"><label>Last name</label><input id="rc14PFLast" value="${rc15Escape(c.lastName||'')}"></div><div class="field"><label>Email / login ID</label><input value="${rc15Escape(c.email||'')}" disabled></div><div class="field"><label>Phone</label><input id="rc14PFPhone" value="${rc15Escape(c.phone||'')}"></div><div class="field"><label>WhatsApp</label><input id="rc15PFWhatsApp" value="${rc15Escape(c.whatsapp||c.phone||'')}"></div><div class="field"><label>Secondary phone</label><input id="rc14PFPhone2" value="${rc15Escape(c.secondaryPhone||'')}"></div><div class="field"><label>Registration / SIRET / SIREN</label><input id="rc14PFRegistration" value="${rc15Escape(c.registrationNumber||c.siret||'')}"></div><div class="field"><label>VAT / Tax ID</label><input id="rc14PFVAT" value="${rc15Escape(c.vatNumber||'')}"></div><div class="field full"><label>Address</label><input id="rc14PFAddress1" value="${rc15Escape(c.address1||'')}"></div><div class="field"><label>Address line 2</label><input id="rc14PFAddress2" value="${rc15Escape(c.address2||'')}"></div><div class="field"><label>Postal code</label><input id="rc14PFPostal" value="${rc15Escape(c.postalCode||'')}"></div><div class="field"><label>City</label><input id="rc14PFCity" value="${rc15Escape(c.city||'')}"></div><div class="field"><label>Website</label><input id="rc14PFWebsite" value="${rc15Escape(c.website||'')}"></div><div class="field"><label>Preferred language</label><select id="rc14PFLang"><option value="en" ${c.preferredLanguage==='en'?'selected':''}>English</option><option value="fr" ${c.preferredLanguage==='fr'?'selected':''}>French</option><option value="es" ${c.preferredLanguage==='es'?'selected':''}>Spanish</option></select></div></div><div class="toolbar"><button class="btn primary" id="rc14PFSave">Save profile changes</button></div></section><section class="rc11-panel" style="margin-top:14px"><div class="rc11-section-head"><div><span class="eyebrow">DOCUMENT VAULT</span><h3>Identity, company & compliance documents</h3><p>Upload from phone camera or device files. Your authorized administrators can review the same documents.</p></div></div>${rc15DocTabs(c.id,RC15_DOC_TYPES)}<div class="rc15-resource-grid" style="margin-top:12px">${Object.entries(RC15_DOC_TYPES).map(([k,v])=>`<div class="rc14-file-field"><label>${rc15Escape(v.label)} ${v.required?'<b>*</b>':''}</label><input type="file" data-rc15-profile-upload="${k}" accept="${rc15Escape(v.accept)}" ${k==='portrait'?'capture="user"':''}></div>`).join('')}</div><div class="toolbar"><button class="btn primary" id="rc15PFUploadDocs">Upload selected documents</button></div></section>`}
async function rc15UploadProfessionalDocs(){const c=currentClient(),inputs=[...document.querySelectorAll('[data-rc15-profile-upload]')];let n=0;for(const inp of inputs){const f=inp.files?.[0];if(!f)continue;if(f.size>RC15_FILE_MAX){toast(`${f.name} exceeds 50 MB.`);continue}await rc14StoreProfileDocument(c.id,inp.dataset.rc15ProfileUpload,f);n++}saveStore();toast(`${n} document(s) uploaded.`);renderShell()}

/* 10 — 24-hour temporary credential lifecycle, exact-role login, first-login password confirmation. */
async function rc15UniqueTemporaryPassword(){const chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%';for(let tries=0;tries<12;tries++){const arr=new Uint32Array(18);crypto.getRandomValues(arr);let pw='';for(const v of arr)pw+=chars[v%chars.length];const h=await hashText(pw);if(!rc15Settings().issuedCredentialHashes.includes(h)){rc15Settings().issuedCredentialHashes.push(h);if(rc15Settings().issuedCredentialHashes.length>50000)rc15Settings().issuedCredentialHashes.splice(0,10000);return{pw,hash:h}}}throw new Error('Unable to generate unique credential')}
function rc15CredentialMail(person,pw,kind){return{subject:`RENOVO CRETE — ${kind} temporary portal access`,body:`Welcome ${person.name||person.contact||person.company||''},\n\nYour RENOVO CRETE ${kind} portal access is ready.\n\nLogin / email: ${person.email}\nTemporary password: ${pw}\n\nThis temporary password is valid for 24 hours. On first login you can confirm it as your password or create your own password. After 24 hours an unconfirmed temporary password expires and a new access credential must be requested.\n\nRENOVO CRETE`}}
function rc15ApplyTemporaryCredential(acc,hash,role){acc.passwordHash=hash;acc.tempCredentialIssuedAt=new Date().toISOString();acc.tempCredentialExpiresAt=new Date(Date.now()+24*3600*1000).toISOString();acc.mustConfirmPassword=true;acc.credentialRole=role;acc.loginPending=false}
rc14IssueCredential=async function(clientId,send=true){const c=store.accounts.find(x=>x.id===clientId&&x.role==='client');if(!c||!rc11CanManageClient(c))return toast('No permission.');if(!c.email)return toast('Email required.');const{pw,hash}=await rc15UniqueTemporaryPassword();rc15ApplyTemporaryCredential(c,hash,'client');if(c.status!=='pending'){c.active=true;c.status='approved'}saveStore();const m=rc15CredentialMail({...c,name:rcClientName(c)},pw,'professional');if(send){try{const mode=await rc14DeliverEmail(c.email,m.subject,m.body);toast(mode==='sent'?'24-hour credentials sent.':'24-hour credential email draft prepared.')}catch(e){toast('Credential created; email connector failed.')}}return{c,pw,...m}};
rc14BulkCredentials=async function(ids){const list=[...new Set(ids)].map(id=>store.accounts.find(c=>c.id===id&&c.role==='client')).filter(c=>c&&rc11CanManageClient(c)&&c.email);if(!list.length)return toast('Select at least one manageable professional.');const useProxy=!!rc14Settings().transactionalEmail.proxyUrl,out=[];for(const c of list){const{pw,hash}=await rc15UniqueTemporaryPassword();rc15ApplyTemporaryCredential(c,hash,'client');if(c.status!=='pending'){c.active=true;c.status='approved'}const m=rc15CredentialMail({...c,name:rcClientName(c)},pw,'professional');let delivery='prepared';if(useProxy){try{await rc14DeliverEmail(c.email,m.subject,m.body);delivery='sent'}catch(e){delivery='failed'}}out.push({company:c.company,email:c.email,password:pw,expires:new Date(c.tempCredentialExpiresAt).toLocaleString(),delivery})}saveStore();if(useProxy)toast(`${out.filter(x=>x.delivery==='sent').length}/${out.length} credential email(s) sent.`);else rc15CsvDownload(`RENOVO_CRETE_24h_Credentials_${new Date().toISOString().slice(0,10)}.csv`,[['Company','Email','Temporary password','Expires','Delivery'],...out.map(x=>[x.company,x.email,x.password,x.expires,x.delivery])])};
rc14IssueAdminCredential=async function(profileId){const p=rc11AdminProfile(),a=store.adminProfiles.find(x=>x.id===profileId);if(!a||!(rc12IsWorldHq(p)||rc12IsCaribbeanHq(p)||a.id===p?.id))return toast('No permission.');const acc=store.accounts.find(x=>x.adminProfileId===a.id);if(!acc||!a.email)return toast('Administrator login account/email missing.');const{pw,hash}=await rc15UniqueTemporaryPassword();rc15ApplyTemporaryCredential(acc,hash,'admin');a.lastCredentialIssuedAt=new Date().toISOString();saveStore();const m=rc15CredentialMail({...a,name:a.name},pw,'administrator');try{const mode=await rc14DeliverEmail(a.email,m.subject,m.body);toast(mode==='sent'?'24-hour administrator credentials sent.':'Administrator email draft prepared.')}catch(e){toast('Credential created; email delivery failed.')}};
function rc15CompleteLogin(a){session={accountId:a.id,impersonatedClientId:null};currentView=a.role==='admin'?'admin-dashboard':'dashboard';saveStore();showApp();if(a.mustConfirmPassword)setTimeout(()=>rc15PasswordConfirmation(a.id),120)}
function rc15PasswordConfirmation(accountId){const a=store.accounts.find(x=>x.id===accountId);if(!a?.mustConfirmPassword)return;showModal(`<div class="rc11-modal-wide"><span class="eyebrow">FIRST LOGIN SECURITY</span><h2>Confirm your password</h2><p>The temporary password is valid for 24 hours only. Confirm it as your permanent password, or create your own password now.</p><div class="rc12-modal-grid"><div class="field full"><label>Create new password</label><input id="rc15NewPassword" type="password" autocomplete="new-password" placeholder="Minimum 10 characters"></div><div class="field full"><label>Confirm new password</label><input id="rc15NewPassword2" type="password" autocomplete="new-password"></div></div><div class="toolbar"><button class="btn secondary" id="rc15KeepPassword">Keep current password</button><button class="btn primary" id="rc15ChangePassword">Create my password</button><button class="btn danger" id="rc15LogoutTemp">Sign out</button></div></div>`);$('rc15KeepPassword').onclick=()=>{a.mustConfirmPassword=false;delete a.tempCredentialExpiresAt;delete a.tempCredentialIssuedAt;saveStore();closeModal();toast('Current password confirmed.')};$('rc15ChangePassword').onclick=async()=>{const p=$('rc15NewPassword').value,p2=$('rc15NewPassword2').value;if(p.length<10||p!==p2)return toast('Use 10+ characters and matching passwords.');a.passwordHash=await hashText(p);a.mustConfirmPassword=false;delete a.tempCredentialExpiresAt;delete a.tempCredentialIssuedAt;saveStore();closeModal();toast('Personal password created.')};$('rc15LogoutTemp').onclick=()=>{closeModal();session=null;saveStore();showAuth()}}
login=async function(){const email=$('loginEmail').value.trim().toLowerCase(),pw=$('loginPassword').value,hash=await hashText(pw),candidates=store.accounts.filter(x=>String(x.email||'').toLowerCase()===email&&x.active),matches=candidates.filter(x=>x.passwordHash===hash);if(!matches.length)return toast('Incorrect credentials or account not approved.');const valid=matches.filter(a=>!(a.mustConfirmPassword&&a.tempCredentialExpiresAt&&Date.now()>new Date(a.tempCredentialExpiresAt).getTime()));if(!valid.length)return toast('This temporary password expired after 24 hours. Request a new access credential.');if(valid.length===1)return rc15CompleteLogin(valid[0]);showModal(`<h3>Select your profile</h3><p>This email is linked to several authorized profiles. Choose the exact profile you are opening.</p>${valid.map(a=>{const p=a.role==='admin'?store.adminProfiles.find(x=>x.id===a.adminProfileId):a;return`<button class="rc15-folder-card" style="width:100%;margin:6px 0;text-align:left" data-rc15-login-account="${a.id}"><b>${rc15Escape(a.role==='admin'?(p?.name||a.contact):(a.company||a.contact))}</b><small>${rc15Escape(a.role==='admin'?'Administrator':'Professional')} · ${rc15Escape(rc11RegionName(a.regionId||p?.regionId))} · ${rc15Escape(rc11Territory(a.territoryId||p?.territoryId)?.name||'')}</small></button>`}).join('')}<button class="btn secondary" onclick="closeModal()">Cancel</button>`);document.querySelectorAll('[data-rc15-login-account]').forEach(b=>b.onclick=()=>{closeModal();rc15CompleteLogin(store.accounts.find(x=>x.id===b.dataset.rc15LoginAccount))})};

/* 7 & 12 — Administrator WhatsApp, photo/doc vault and multi-territory assignment. */
const rc15BaseAdminEditor=rc11OpenAdminEditor;
rc11OpenAdminEditor=function(id=''){rc15BaseAdminEditor(id);setTimeout(()=>{const modal=document.querySelector('.modal-card .rc11-modal-wide');if(!modal)return;const a=store.adminProfiles.find(x=>x.id===id),grid=modal.querySelector('.rc12-modal-grid');if(grid&&!$('rc15AdminWhatsApp'))grid.insertAdjacentHTML('beforeend',`<div class="field"><label>WhatsApp</label><input id="rc15AdminWhatsApp" value="${rc15Escape(a?.whatsapp||a?.phone||'')}"></div>`);const save=$('rc11SaveAdmin');if(save&&!save.dataset.rc15Wrapped){save.dataset.rc15Wrapped='1';save.addEventListener('click',()=>{const email=$('rc11AdminEmail')?.value.trim().toLowerCase(),wa=$('rc15AdminWhatsApp')?.value.trim();setTimeout(()=>{const prof=store.adminProfiles.find(x=>x.id===id)||store.adminProfiles.find(x=>String(x.email||'').toLowerCase()===email);if(prof){prof.whatsapp=wa;saveStore()}},80)},true)}},0)};
const rc15BaseAdminSheet=rc13OpenAdminSheet;
rc13OpenAdminSheet=function(id){rc15BaseAdminSheet(id);setTimeout(()=>{const a=store.adminProfiles.find(x=>x.id===id),card=document.querySelector('.modal-card .rc13-profile-sheet');if(!a||!card)return;const photo=rc15ProfilePhotoDoc('admin:'+id),head=card.querySelector('.rc13-profile-head');if(head&&!head.querySelector('.rc15-profile-avatar'))head.insertAdjacentHTML('afterbegin',`<img class="rc15-profile-avatar" ${photo?`data-rc15-photo-doc="${photo.id}"`:''} alt="Administrator photo">`);const grid=card.querySelector('.rc13-profile-grid');if(grid)grid.insertAdjacentHTML('beforeend',`<section><h4>WhatsApp & assignments</h4><p><b>WhatsApp:</b> ${rc15Escape(a.whatsapp||a.phone||'—')}</p><div class="rc15-assignment-chips">${[a.territoryId,...(a.extraTerritoryIds||[])].filter(Boolean).map(tid=>`<span class="rc15-assignment">${rc15FlagForTerritory(rc11Territory(tid))} ${rc15Escape(rc11Territory(tid)?.name||tid)}</span>`).join('')}</div></section>`);const notes=card.querySelector('.rc13-notes');if(notes)notes.insertAdjacentHTML('afterend',`<section class="rc13-notes"><h4>Administrator identity / contract documents</h4>${rc15DocTabs('admin:'+id,RC15_ADMIN_DOC_TYPES)}<div class="rc15-resource-grid">${Object.entries(RC15_ADMIN_DOC_TYPES).map(([k,v])=>`<div class="rc14-file-field"><label>${rc15Escape(v.label)}</label><input type="file" data-rc15-admin-upload="${k}" accept="${rc15Escape(v.accept)}" ${k==='portrait'?'capture="user"':''}></div>`).join('')}</div><button class="btn secondary small" data-rc15-admin-upload-save="${id}">Upload selected administrator documents</button></section>`);const tb=card.querySelector('.toolbar');if(tb&&rc11CanManageAdmin(a)){const b=document.createElement('button');b.className='btn secondary';b.textContent='Copy / assign to another territory';b.dataset.rc15AssignAdmin=id;tb.insertBefore(b,tb.lastElementChild)}rc15HydrateProfileImages()},0)};
function rc15AssignAdminTerritory(id){const a=store.adminProfiles.find(x=>x.id===id),p=rc11AdminProfile();if(!a||!rc11CanManageAdmin(a,p))return;const allowed=rc11Territories().filter(t=>rc12CanSeeTerritory(t.id,p)&&t.id!==a.territoryId&&!(a.extraTerritoryIds||[]).includes(t.id));showModal(`<h3>Copy administrator assignment</h3><p>The identity/login remains unique. This adds an authorized territory to the same administrator profile.</p><div class="field"><label>Additional territory</label><select id="rc15AdminAssignTerr">${allowed.map(t=>`<option value="${t.id}">${rc15FlagForTerritory(t)} ${rc15Escape(rc11RegionName(t.regionId))} · ${rc15Escape(t.name)}</option>`).join('')}</select></div><div class="toolbar"><button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn primary" id="rc15AdminAssignSave">Assign</button></div>`);$('rc15AdminAssignSave').onclick=()=>{const tid=$('rc15AdminAssignTerr').value,t=rc11Territory(tid);a.extraTerritoryIds=[...new Set([...(a.extraTerritoryIds||[]),tid])];if(t&&t.regionId!==a.regionId)a.extraRegionIds=[...new Set([...(a.extraRegionIds||[]),t.regionId])];saveStore();closeModal();rc13OpenAdminSheet(id)}}
async function rc15UploadAdminDocuments(id){const inputs=[...document.querySelectorAll('[data-rc15-admin-upload]')];let n=0;for(const inp of inputs){const f=inp.files?.[0];if(!f)continue;if(f.size>RC15_FILE_MAX){toast(`${f.name} exceeds 50 MB.`);continue}await rc14StoreProfileDocument('admin:'+id,inp.dataset.rc15AdminUpload,f);n++}saveStore();toast(`${n} administrator document(s) uploaded.`);closeModal();rc13OpenAdminSheet(id)}

/* 11 — HQ-only optional 3-grid platform access pricing, disabled by default. */
function rc15PlatformFeatureOptions(plan){const all=[['calculator','System calculator'],['orders','Product orders'],['invoices','Invoices'],['documentation','Documentation'],['events','Events & training'],['community','Community'],['visualizer','Floor visualizer'],['priority-support','Priority support']];return all.map(([id,label])=>`<label class="rc15-plan-feature"><input type="checkbox" data-rc15-plan-feature="${plan.id}|${id}" ${plan.features.includes(id)?'checked':''}> ${label}</label>`).join('')}
function renderPlatformAccessV15(){if(!rc15IsHQ())return rc11Hero('Platform access','USA HQ Indiana and Saint-Martin Caribbean HQ only.','HQ CONTROL','',[])+`<div class="notice warn">No permission.</div>`;const s=rc15Settings().platformAccess,people=[...rc11VisibleClients().map(c=>({id:c.id,name:c.company,kind:'Professional',region:c.regionId,territory:c.territoryId})),...store.adminProfiles.filter(a=>a.level==='regional_admin').map(a=>({id:'admin:'+a.id,name:a.name,kind:'Administrator',region:a.regionId,territory:a.territoryId}))];return rc11Hero('Platform access pricing','Three optional access grids. This commercial layer is hidden everywhere while disabled. HQ can enable it and assign Free or a paid grid by person/territory.','HQ ACCESS MONETIZATION','',[s.enabled?'Enabled':'Disabled'])+`<section class="rc11-panel"><label class="permission-line"><input id="rc15PlatformEnabled" type="checkbox" ${s.enabled?'checked':''}> Enable platform access pricing / paywall controls</label><p>When disabled, no professional or regional administrator sees this commercial access layer.</p></section><div class="rc15-plan-grid" style="margin-top:14px">${s.plans.map((p,i)=>`<article class="rc15-plan"><span class="eyebrow">GRID ${i+1}</span><h3><input data-rc15-plan-name="${p.id}" value="${rc15Escape(p.name)}"></h3><div class="rc15-price-input"><div class="field"><label>EUR</label><input type="number" data-rc15-plan-eur="${p.id}" value="${Number(p.priceEUR||0)}"></div><div class="field"><label>USD (auto)</label><input disabled value="${(Number(p.priceEUR||0)*rc15Rate('REGION:CARIBBEAN')).toFixed(2)}"></div></div>${rc15PlatformFeatureOptions(p)}</article>`).join('')}</div><section class="rc11-panel" style="margin-top:14px"><div class="rc11-section-head"><div><span class="eyebrow">ASSIGNMENTS</span><h3>Free / paid access by person</h3></div><button class="btn primary" id="rc15SavePlatform">Save & synchronize</button></div><div class="table-wrap"><table class="rc11-table"><thead><tr><th>Name</th><th>Type</th><th>Region</th><th>Territory</th><th>Access</th></tr></thead><tbody>${people.map(x=>`<tr><td>${rc15Escape(x.name)}</td><td>${x.kind}</td><td>${rc15Escape(rc11RegionName(x.region))}</td><td>${rc15Escape(rc11Territory(x.territory)?.name||'')}</td><td><select data-rc15-access-person="${x.id}"><option value="free">Free</option>${s.plans.map(p=>`<option value="${p.id}" ${s.assignments[x.id]===p.id?'selected':''}>${rc15Escape(p.name)}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div></section>`}
function rc15BindPlatform(){if(!rc15IsHQ())return;$('rc15SavePlatform')?.addEventListener('click',()=>{const s=rc15Settings().platformAccess;s.enabled=$('rc15PlatformEnabled').checked;s.plans.forEach(p=>{p.name=document.querySelector(`[data-rc15-plan-name="${p.id}"]`)?.value.trim()||p.name;p.priceEUR=Number(document.querySelector(`[data-rc15-plan-eur="${p.id}"]`)?.value||0);p.features=[...document.querySelectorAll(`[data-rc15-plan-feature^="${p.id}|"]:checked`)].map(x=>x.dataset.rc15PlanFeature.split('|')[1])});document.querySelectorAll('[data-rc15-access-person]').forEach(sel=>{if(sel.value==='free')delete s.assignments[sel.dataset.rc15AccessPerson];else s.assignments[sel.dataset.rc15AccessPerson]=sel.value});saveStore();toast('Platform access grids synchronized.')})}

/* Region cards: country/state flag visualization. */
function rc15HydrateRegionFlags(){document.querySelectorAll('[data-rc12-territory-detail],[data-rc13-territory-open]').forEach(b=>{const id=b.dataset.rc12TerritoryDetail||b.dataset.rc13TerritoryOpen,t=rc11Territory(id);if(t&&!b.dataset.rc15Flagged){b.dataset.rc15Flagged='1';b.insertAdjacentHTML('afterbegin',`<span class="rc15-country-flag">${rc15FlagForTerritory(t)}</span>`)}})}

/* Navigation additions. */
const rc15BaseSyncNav=rc11SyncNavDefinitions;
rc11SyncNavDefinitions=function(){rc15BaseSyncNav();const ensure=(arr,tab,before)=>{if(arr.some(x=>x[0]===tab[0]))return;const i=arr.findIndex(x=>x[0]===before);arr.splice(i>=0?i:arr.length,0,tab)};ensure(RC101_CLIENT_TABS,['community','◉','Community'],'support');ensure(RC101_ADMIN_TABS,['community','◉','MD Community'],'admin-messages');if(rc15IsHQ())ensure(RC101_ADMIN_TABS,['platform-access','◆','Platform access plans'],'admin-settings')};

/* Content router. */
const rc15BaseRenderContent=renderContent;
renderContent=function(){if(currentView==='community'){$('content').innerHTML=renderCommunityV15();bindView();return}if(currentView==='platform-access'){$('content').innerHTML=renderPlatformAccessV15();bindView();return}rc15BaseRenderContent()};

/* Binding aggregation. */
const rc15BaseBindController=rc11BindController;
rc11BindController=function(){rc15BaseBindController();
 if(currentView==='admin-dashboard')rc15BindDashboardLinks();
 if(currentView==='dashboard')rc15BindProfessionalDashboard();
 if(currentView==='documentation'||currentView==='admin-documentation')rc15BindKnowledge();
 if(currentView==='events')rc15BindCalendar(false);
 if(currentView==='admin-events')rc15BindCalendar(true);
 if(currentView==='admin-catalog')rc15BindCatalog();
 if(currentView==='portfolio')rc15BindPortfolio();
 if(currentView==='community')rc15BindCommunity();
 if(currentView==='platform-access')rc15BindPlatform();
 if(currentView==='profile'){$('rc15PFUploadDocs')?.addEventListener('click',rc15UploadProfessionalDocs);$('rc14PFSave')?.addEventListener('click',()=>{const c=currentClient();if(c)c.whatsapp=$('rc15PFWhatsApp')?.value.trim()||c.phone||'';saveStore()},true);setTimeout(rc15HydrateProfileImages,0)}
 rc15HydrateRegionFlags();
};

/* Delegated actions for dynamic sheets / attachments. */
if(!window.__rc15Delegated){window.__rc15Delegated=true;document.addEventListener('click',e=>{const b=e.target.closest('[data-rc15-assign-admin],[data-rc15-admin-upload-save],[data-rc15-assign-pro]');if(!b)return;if(b.dataset.rc15AssignAdmin){e.preventDefault();rc15AssignAdminTerritory(b.dataset.rc15AssignAdmin)}else if(b.dataset.rc15AdminUploadSave){e.preventDefault();rc15UploadAdminDocuments(b.dataset.rc15AdminUploadSave)}else if(b.dataset.rc15AssignPro){e.preventDefault();rc15AssignProfessionalTerritory(b.dataset.rc15AssignPro)}})}

/* Final shell hook: maintain scroll ergonomics and page hydration. */
const rc15BaseRenderShell=renderShell;
renderShell=function(){const out=rc15BaseRenderShell();setTimeout(()=>{if(currentView==='admin-dashboard')rc15BindDashboardLinks();if(currentView==='dashboard')rc15BindProfessionalDashboard();rc15HydrateRegionFlags();rc15HydrateProfileImages()},0);return out};

rc15Settings();
